parameters.jsCode:
// The portal answers with one object containing an items array; n8n works
// in items. Fan the array out so every downstream node handles one post.
//
// A run id is stamped on each item here rather than per node, so every log
// line and every callback for this execution shares one identifier — which is
// what makes 'show me everything that happened to this post tonight'
// answerable later.
const response = $input.first().json;

if (!response.ok) {
  throw new Error(`Portal refused the queue request: ${response.error || 'unknown error'}`);
}

const runId = `n8n-${$execution.id}`;

return (response.items || []).map((item) => ({
  json: { ...item, run_id: runId, started_at: new Date().toISOString() },
}));

// Build the container request. Reels and stills take different fields, and
// Meta rejects a container whose media_type doesn't match the file it is
// given — so the shape is decided here, once, from what the portal said the
// asset actually is.
//
// The token is picked here too: a client whose Instagram account sits outside
// the agency's Business Manager carries its own page token, everyone else
// uses the agency-wide one from n8n's environment.
const item = $('Claim the deliverable').item.json.item;
const apiVersion = $env.META_API_VERSION || 'v21.0';
const token = item.ig_access_token || $env.META_ACCESS_TOKEN;

if (!token) {
  throw new Error('No Meta access token: set META_ACCESS_TOKEN, or give the client its own ig_access_token.');
}
if (!item.video_url) {
  throw new Error('The deliverable has no fetchable media URL — check Cloudflare R2 is configured.');
}

// Instagram fetches the file from this URL itself, so it has to be publicly
// reachable for the life of the request. A signed R2 link is fine; a Google
// Drive share link is not — it serves an HTML page, not video bytes.
const body = item.media_type === 'IMAGE'
  ? { image_url: item.video_url, caption: item.caption }
  : { media_type: 'REELS', video_url: item.video_url, caption: item.caption, share_to_feed: true };

return [{
  json: {
    ...item,
    run_id: $('Split queue into items').first().json.run_id,
    api_version: apiVersion,
    access_token: token,
    container_url: `https://graph.facebook.com/${apiVersion}/${item.ig_user_id}/media`,
    container_body: { ...body, access_token: token },
    poll_count: 0,
    publish_started_at: Date.now(),
  },
}];

// Decide what the container's status means, and keep the poll counter.
//
// n8n has no loop counter of its own — looping back to Wait would poll for
// ever if Meta got stuck. The count is carried on the item instead, and
// exceeding it is treated as a real failure rather than an infinite retry.
const MAX_POLLS = 12; // 12 × 30s = 6 minutes

const built = $('Build Graph API request').item.json;
const status = $json.status_code || $json.status || 'UNKNOWN';
const pollCount = (built.poll_count || 0) + 1;

let outcome;
if (status === 'FINISHED') {
  outcome = 'ready';
} else if (status === 'ERROR' || status === 'EXPIRED') {
  outcome = 'failed';
} else if (pollCount >= MAX_POLLS) {
  outcome = 'timeout';
} else {
  outcome = 'waiting';
}

return [{
  json: {
    ...built,
    poll_count: pollCount,
    container_id: $('Create media container').item.json.id,
    container_status: status,
    outcome,
    error_message: outcome === 'failed'
      ? `Instagram could not process the media (status ${status}). The file is usually too long, the wrong aspect ratio, or an unsupported codec.`
      : outcome === 'timeout'
        ? `Instagram was still encoding after ${MAX_POLLS * 30} seconds.`
        : null,
  },
}];

