parameters.jsCode:
// Normalise every failure into one shape before reporting it.
//
// Failures arrive from four different places (container creation, encoding,
// publishing, and this node's own callers) with four different bodies. The
// portal wants one contract, and — importantly — Meta's numeric error code,
// because that is what tells it whether retrying could ever help.
const sources = ['Build Graph API request', 'Interpret status'];
let context = {};
for (const name of sources) {
  try {
    context = { ...context, ...$(name).item.json };
  } catch {
    // The node didn't run on this path — expected, not an error.
  }
}

const body = $json || {};
const graphError = body.error || {};

// A Graph error body looks like { error: { message, code, error_subcode } }.
const errorCode = graphError.code != null ? String(graphError.code) : null;
const message =
  context.error_message ||
  graphError.error_user_msg ||
  graphError.message ||
  body.message ||
  'Instagram publishing failed for an unknown reason.';

return [{
  json: {
    deliverable_id: context.deliverable_id,
    run_id: context.run_id,
    status: 'failed',
    stage: context.container_id ? 'publish' : 'create_container',
    error_code: errorCode,
    error_message: message,
    // The portal also knows Meta's permanent codes; this flag is for failures
    // only the workflow can recognise, such as a missing media file.
    permanent: /unsupported|invalid.*aspect|too long|not eligible/i.test(message),
  },
}];
